import{_ as o,o as a,c as t,a3 as i}from"./chunks/framework.CWSmAuPU.js";const p=JSON.parse('{"title":"0033 原型审查页和不靠看图的界面检查","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0033-prototype-review-and-ui-check.md","filePath":"reference/adr/0033-prototype-review-and-ui-check.md","lastUpdated":null}'),r={name:"reference/adr/0033-prototype-review-and-ui-check.md"};function d(c,e,l,n,s,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<div><h1 id="_0033-原型审查页和不靠看图的界面检查" tabindex="-1">0033 原型审查页和不靠看图的界面检查 <a class="header-anchor" href="#_0033-原型审查页和不靠看图的界面检查" aria-label="Permalink to &quot;0033 原型审查页和不靠看图的界面检查&quot;">​</a></h1><ul><li>状态：已采纳（1.13.0-beta.2）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>内网的使用者有三个限制：</p><ul><li>只能用 Paseo 网页端（桌面端有安装限制），所以 Paseo 内置浏览器和它的 <code>browser_*</code> 工具用不了，1.8 起的&quot;浏览器验证&quot;实际上从不运行。</li><li>内网模型看图能力弱：截图交给它判断界面对不对，效果差，每张图还要消耗不少 token。</li><li>需求方多数不是开发者，确认方案时看得出&quot;不对&quot;，但说不清哪里不对、要改成什么；插件里只有一个文本框写修改意见。插件页面也不能显示 HTML，原型只能在功能目录里自己找文件打开。</li></ul><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>原型审查页</strong>：一个本机网页（<code>engine/src/review.ts</code>），插件和 <code>req review</code> 打开它。需求方在原型上点选、选改法、补一句话，页面记下被点元素的文字、颜色、字号、大小、所在区域和对应的 AC；双击可以直接改文字。提交时整理成一份带位置信息的清单，经已有的 <code>req reply</code> 转给需求会话，确认方案经 <code>req approve</code>：不增加新的流程分支。 <ul><li>原型由 agent 生成，内容可能来自卡片等外部文字，和提交接口同源。所以原型以 <code>script-src &#39;none&#39;</code> 返回，里面的脚本不运行，审查页从外面读写它的 DOM。</li><li>服务只监听 <code>127.0.0.1</code>，地址带随机令牌；另有一个只读令牌。远程访问要显式设置环境变量。</li><li>每次打开时保存原型的版本，改过后用文字差异标出变化，需求方不用自己找改了哪里。</li><li>方案设计的提示词规定原型的写法（<code>data-ac</code>、<code>data-label</code>、<code>data-state</code>、真实文字），审查页和界面检查都依赖它。</li></ul></li><li><strong>界面检查 <code>req ui-check</code></strong>：用 <code>playwright-core</code> 驱动本机的 Edge 或 Chrome（不下载浏览器，驱动在第一次使用时从 npm 源装到 <code>~/.req-kit/tools</code>），在页面里运行一段固定的脚本，用文字报告看得出的版面问题，并拿原型里的标题、按钮、字段名、表头和页面对文字。结果是确定的，不依赖模型看图。截图只存文件给人看。验证类步骤总是附上它；有 Paseo 浏览器时，同一段脚本也可以用 <code>browser_evaluate</code> 运行。</li><li>对比度只报明显看不清的（低于 3:1，大字 2.5:1），不报 WCAG 4.5:1 的边缘情况：常见组件库的主按钮正好在这个边缘，全报会淹没真正的问题。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>需求方确认方案的方式从&quot;写一段话&quot;变成&quot;在原型上点&quot;，修改意见能直接定位到元素。效果要看原型是否按约定标了区域。</li><li>验证不再依赖桌面端和模型的视觉能力；需要本机有 Edge 或 Chrome（Windows 自带 Edge）。</li><li><code>req ui-check</code> 第一次运行要能从 npm 源取到 <code>playwright-core</code>，内网走镜像。</li><li>只检查&quot;看得出的&quot;问题，不判断设计是否好看；&quot;和原型对文字&quot;只比较标签类文字，原型中的示例数据不比较。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0033-prototype-review-and-ui-check.md">docs/adr/0033-prototype-review-and-ui-check.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0033-prototype-review-and-ui-check.md">在 GitHub 上编辑</a></p>',2)])])}const q=o(r,[["render",d]]);export{p as __pageData,q as default};
